from __future__ import annotations

"""Spotify Web API paging objects for the Saved Tracks library.

``GET /v1/me/tracks`` returns a paging object::

    {
        "items": [{"added_at": "...", "track": {"id": "...", "name": "..."}}],
        "next": "https://api.spotify.com/v1/me/tracks?offset=50&limit=50",
        "limit": 50, "offset": 0, "total": 312
    }

A page can hold fewer than ``limit`` items even when it is not the last page —
items unavailable in the user's market or removed by relinking get dropped from
that page while ``next`` still points at more results. The only reliable
end-of-collection signal is ``next`` being null.
"""

from dataclasses import dataclass
from urllib.parse import parse_qs, urlparse

API_BASE = "https://api.spotify.com/v1/me/tracks"


def next_page_url(offset: int, limit: int) -> str:
    return f"{API_BASE}?offset={offset}&limit={limit}"


@dataclass(frozen=True)
class SavedTrack:
    added_at: str
    track_id: str
    track_name: str

    def __post_init__(self) -> None:
        if not self.track_id.strip():
            raise ValueError("track_id is required")
        if not self.added_at.strip():
            raise ValueError("added_at is required")


@dataclass(frozen=True)
class SavedTrackPage:
    items: tuple[SavedTrack, ...]
    next: str | None
    limit: int
    offset: int
    total: int

    def has_next(self) -> bool:
        return self.next is not None

    def next_offset(self) -> int | None:
        if self.next is None:
            return None
        query = parse_qs(urlparse(self.next).query)
        values = query.get("offset")
        if not values:
            return None
        return int(values[0])

    @classmethod
    def from_raw(cls, raw: dict) -> "SavedTrackPage":
        items = []
        for entry in raw.get("items", []):
            track = entry.get("track") or {}
            items.append(
                SavedTrack(
                    added_at=str(entry.get("added_at", "")),
                    track_id=str(track.get("id", "")),
                    track_name=str(track.get("name", "")),
                )
            )
        return cls(
            items=tuple(items),
            next=raw.get("next"),
            limit=int(raw.get("limit", len(items))),
            offset=int(raw.get("offset", 0)),
            total=int(raw.get("total", len(items))),
        )


class PagedLibrary:
    """A scripted Saved Tracks library that serves pages by offset."""

    def __init__(self, pages: list[SavedTrackPage]) -> None:
        if not pages:
            raise ValueError("a library needs at least one page")
        self._by_offset = {page.offset: page for page in pages}
        self.request_count = 0

    def get_page(self, offset: int, limit: int) -> SavedTrackPage:
        page = self._by_offset.get(offset)
        if page is None:
            raise ValueError(f"no page at offset {offset}")
        self.request_count += 1
        return page

    def first_offset(self) -> int:
        return min(self._by_offset)


def build_library(raw_pages: list[dict]) -> PagedLibrary:
    return PagedLibrary([SavedTrackPage.from_raw(raw) for raw in raw_pages])

